<script>
 import { onMount, tick } from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import { booksWindow,booksSelected,booksVisible,booksCapabilities,booksFraction } from './books-state.js';
 import { BOOKS_SEEDS,EPUB_MIME,searchEpub } from './books-epub.js';
 import { booksMenus,createBooksNativeView } from './books-commands.js';
 let { state: booksState,profile,windowId,execute,registerView,readBook,getFile,available=true,active=true,controls={} }=$props();
 let root=$state(null),document=$state.raw(null),documentFile=$state.raw(null),loading=$state(false),message=$state(''),covers=$state.raw({}),collectionName=$state(''),collectionId=$state(''),accountName=$state(''),accountEmail=$state(''),note=$state(''),highlightColor=$state('yellow'),storeQuery=$state('');
 let originalState,originalProfile,originalId,originalSession,retired=false,facade,loadSequence=0,restoredKey='',scrollFrame=0;
 const session=$derived(booksWindow(booksState,windowId)),selected=$derived(booksSelected(booksState,session)),cap=$derived(booksCapabilities(profile)),visible=$derived(booksVisible(booksState,session)),menus=$derived(booksMenus({state: booksState,profile,windowId}));
 const chapter=$derived(session?.reader&&document?document.chapters[session.location.chapter]:null),matches=$derived(document?searchEpub(document,session?.readerQuery??''):[]);
 const heading=$derived(({all:cap.classic?'All Books':'All',authors:'Authors',categories:'Categories',books:'Books',pdfs:'PDFs',finished:'Finished',store:cap.label==='iBooks'?'iBooks Store':'Book Store',account:'Local Account',downloads:'Downloads'})[session?.section]??booksState.collections.find(c=>`collection:${c.id}`===session?.section)?.name??'Library');
 const groups=$derived(session?.section==='authors'?[...new Set(visible.map(b=>b.author||'Unknown author'))].map(name=>({name,books:visible.filter(b=>(b.author||'Unknown author')===name)})):session?.section==='categories'?[...new Set(visible.flatMap(b=>b.categories.length?b.categories:['Uncategorized']))].sort().map(name=>({name,books:visible.filter(b=>b.categories.length?b.categories.includes(name):name==='Uncategorized')})):[{name:'',books:visible}]);
 function current(){return !retired&&root?.isConnected===true&&booksState===originalState&&profile===originalProfile&&windowId===originalId&&booksWindow(booksState,windowId)===originalSession;}
 async function command(name,payload={},bookId=null){if(!current()||!available||!active)return;const result=await execute(`books.${name}`,{windowId,...(bookId?{bookId}:{})},payload);if(current())message=result?.status==='applied'?'':result?.error?.message??'The local operation is unavailable.';return result;}
 const navigate=section=>command('navigate',{section});
 const panel=kind=>command('reader.panel',{panel:session.panel===kind?'none':kind});
 const typography=(key,value)=>command('reader.typography',{...session.typography,[key]:value});
 function openSheet(kind){if(kind==='collection'){collectionName='';collectionId=session?.section.startsWith('collection:')?session.section.slice(11):'';}return command('sheet',{sheet:kind,menu:null});}
 function readyFile(book){const file=getFile?.(book.fileId);return file&&file.revision===book.fileRevision?file:null;}
 function textRuns(block){const marks=(selected?.annotations??[]).filter(m=>m.chapter===session.location.chapter&&m.start<block.start+block.text.length&&m.end>block.start),hits=matches.filter(m=>m.chapter===session.location.chapter&&m.offset<block.start+block.text.length&&m.end>block.start),points=new Set([0,block.text.length]);for(const m of [...marks,...hits]){points.add(Math.max(0,(m.start??m.offset)-block.start));points.add(Math.min(block.text.length,m.end-block.start));}const edges=[...points].sort((a,b)=>a-b);return edges.slice(0,-1).map((start,i)=>{const end=edges[i+1],mark=marks.find(m=>m.start<=block.start+start&&m.end>=block.start+end),found=hits.some(m=>m.offset<=block.start+start&&m.end>=block.start+end);return {text:block.text.slice(start,end),color:mark?.color??'',note:mark?.note??'',found};});}
 const nativeSelection=()=>facade?.selection()??null;
 const readingLocation=()=>facade?.readingLocation()??null;
 onMount(()=>{originalState=booksState;originalProfile=profile;originalId=windowId;originalSession=session;facade=createBooksNativeView({getRoot:()=>root,getState:()=>booksState,getProfile:()=>profile,windowId,getDocument:()=>document,getDocumentFile:()=>documentFile,getFile:id=>getFile?.(id),available:()=>current()&&available&&active});registerView(windowId,facade);return ()=>{retired=true;loadSequence++;facade.destroy();if(scrollFrame)cancelAnimationFrame(scrollFrame);registerView(originalId,null,facade);};});
 $effect(()=>{const id=selected?.id,reader=session?.reader,file=selected?readyFile(selected):null,revision=file?.revision,bytes=file?.content??file?.text,mounted=root,read=readBook;let stopped=false;if(!mounted||!reader||!file||!read){document=null;documentFile=null;loading=false;return;}const sequence=++loadSequence;loading=true;document=null;documentFile=null;const original=selected;Promise.resolve(read(windowId,id)).then(result=>{if(stopped||!current()||sequence!==loadSequence||booksSelected(booksState,booksWindow(booksState,windowId))!==original||readyFile(original)!==file||file.revision!==revision||(file.content??file.text)!==bytes)return;if(result.error){message=result.error.error?.message??'The EPUB source could not be read.';loading=false;return;}if(result.file!==file||result.guard?.()!==true){loading=false;message='The original EPUB read retired. Return to the library and reopen the actual File.';return;}document=result.document;documentFile=file;loading=false;restoredKey='';message='';}).catch(error=>{if(!stopped&&current()&&sequence===loadSequence){message=error.message;loading=false;}});return ()=>{stopped=true;};});
 $effect(()=>{const ids=visible.slice(0,32).map(b=>[b.id,b.fileId,b.fileRevision,b.mime]),mounted=root,read=readBook;let stopped=false;if(!mounted||!read)return;for(const [id,fileId,revision,mime] of ids){const file=getFile?.(fileId);if(!file||file.revision!==revision||mime!==EPUB_MIME||covers[id]?.file===file&&covers[id]?.revision===revision)continue;Promise.resolve(read(windowId,id)).then(result=>{if(!stopped&&current()&&!result.error&&result.guard?.()===true&&getFile?.(fileId)===file&&file.revision===revision&&result.document.cover)covers={...covers,[id]:{file,revision,src:result.document.cover}};}).catch(()=>{});}return ()=>{stopped=true;};});
 $effect(()=>{const content=chapter,book=selected,offset=session?.location.offset,chapterIndex=session?.location.chapter,mounted=root;if(!content||!mounted||!book)return;const key=`${book.id}:${chapterIndex}:${offset}`;if(key===restoredKey)return;restoredKey=key;let stopped=false;tick().then(()=>{if(stopped||!current()||selected!==book||session.location.chapter!==chapterIndex)return;const area=root.querySelector('[data-book-reader]'),blocks=[...root.querySelectorAll('[data-book-block]')],block=blocks.filter(n=>Number(n.dataset.start)<=offset).at(-1);if(area&&block){area.scrollTop=offset===content.text.length?area.scrollHeight:block.offsetTop-root.querySelector('.chapter-content').offsetTop;}});return ()=>{stopped=true;};});
 function scrolled(){if(scrollFrame||!current()||!active||!available)return;scrollFrame=requestAnimationFrame(async()=>{scrollFrame=0;const actual=readingLocation();if(!actual||actual.chapter===session.location.chapter&&actual.offset===session.location.offset)return;restoredKey=`${selected.id}:${actual.chapter}:${actual.offset}`;await command('reader.progress',actual);});}
 async function saveSelection(){const selection=nativeSelection();if(selection)await command('reader.selection',{selection});}
 async function addAnnotation(){const result=await command('annotation',{operation:'add',color:highlightColor,note});if(result?.status==='applied'){note='';root.ownerDocument.getSelection()?.removeAllRanges();}}
 function key(event){if(!current()||!available||!active||event.target.matches('input,textarea,select'))return;const modifier=cap.windows?event.ctrlKey:event.metaKey;if(event.key==='Escape'){event.preventDefault();if(session.sheet||session.menu)command('sheet',{sheet:null,menu:null});else if(session.panel!=='none')command('reader.panel',{panel:'none'});else if(session.reader)navigate(session.section);}if(session.sheet)return;if(session.reader&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();command('reader.turn',{direction:event.key==='ArrowRight'?1:-1});}if(modifier&&event.key.toLowerCase()==='f'){event.preventDefault();session.reader?command('reader.panel',{panel:'search'}):command('focus',{controlId:'library-search'});}if(modifier&&event.key.toLowerCase()==='o'){event.preventDefault();command('import');}if(event.key==='Enter'&&selected&&!session.reader){event.preventDefault();command('open',{},selected.id);}if(['Delete','Backspace'].includes(event.key)&&selected&&!session.reader){event.preventDefault();openSheet('remove');}}
 async function drop(event){event.preventDefault();if(!current()||!available||!active)return;let ids=[];const plural=event.dataTransfer.getData('application/x-jesteros-file-ids'),single=event.dataTransfer.getData('application/x-jesteros-file-id');try{ids=plural?JSON.parse(plural):single?[single]:[];}catch{message='The actual Files drag payload is invalid.';return;}if(!Array.isArray(ids)||ids.length>128||ids.some(id=>typeof id!=='string')){message='Drop actual canonical Files identifiers only.';return;}for(const id of new Set(ids)){const result=await command('import',{fileId:id});if(result?.status!=='applied')break;}}
 async function menuItem(item){if(!item.enabled||!item.request)return;const result=await execute(item.request.command,item.request.target,item.request.payload);if(current())message=result?.status==='applied'?'':result?.error?.message??'Operation unavailable.';if(result?.status==='applied'&&current()&&session?.menu)command('sheet',{menu:null});}
 async function collection(operation){const result=await command('collection',{operation,...(collectionId?{collectionId}:{}),...(['create','rename'].includes(operation)?{name:collectionName}:{}),...(['add','remove'].includes(operation)&&selected?{bookIds:[selected.id]}:{})});if(result?.status==='applied')command('sheet',{sheet:null});}
</script>

{#snippet cover(book,small=false)}
 <span class="book-cover" class:small style:--cover={book.coverColor??book.color}>
  {#if book.id&&covers[book.id]?.file===readyFile(book)&&covers[book.id]?.revision===book.fileRevision}<img src={covers[book.id].src} alt="" />
  {:else}<span class="cover-rule"></span><span class="cover-author">{book.author}</span><strong>{book.title}</strong><span class="cover-ornament" aria-hidden="true">✧</span><span class="cover-label">{book.mime==='application/pdf'?'PDF':'LOCAL FICTION'}</span>{/if}
 </span>
{/snippet}
{#snippet appearance(value,preference=false)}
 <div class="appearance-controls">
  <div class="size-controls"><button data-book-control="font-smaller" disabled={value.size<=12} onclick={()=>preference?command('preferences',{typography:{...value,size:Math.max(12,value.size-1)}}):typography('size',Math.max(12,value.size-1))}>A</button><span>{value.size} pt</span><button data-book-control="font-larger" disabled={value.size>=36} onclick={()=>preference?command('preferences',{typography:{...value,size:Math.min(36,value.size+1)}}):typography('size',Math.min(36,value.size+1))}>A</button></div>
  <label>Font <select data-book-control="font" value={value.font} onchange={e=>preference?command('preferences',{typography:{...value,font:e.currentTarget.value}}):typography('font',e.currentTarget.value)}><option value="serif">Serif</option><option value="sans">Sans Serif</option><option value="mono">Monospaced</option></select></label>
  <div class="colors" aria-label="Page appearance">{#each ['white','sepia','gray','night'] as color}<button class="swatch {color}" class:chosen={value.appearance===color} data-book-control={'appearance-'+color} aria-label={color} aria-pressed={value.appearance===color} onclick={()=>preference?command('preferences',{typography:{...value,appearance:color}}):typography('appearance',color)}>A</button>{/each}</div>
  <label>Page view <select value={value.layout} data-book-control="page-layout" onchange={e=>preference?command('preferences',{typography:{...value,layout:e.currentTarget.value}}):typography('layout',e.currentTarget.value)}><option value="single">Single Page</option><option value="two">Two Pages</option></select></label>
  <label>Line spacing <input data-book-control="line-spacing" type="range" min="1.2" max="2.2" step="0.1" value={value.lineHeight} oninput={e=>preference?command('preferences',{typography:{...value,lineHeight:Number(e.currentTarget.value)}}):typography('lineHeight',Number(e.currentTarget.value))}/></label>
  <label class="check"><input data-book-control="justify" type="checkbox" checked={value.justify} onchange={e=>preference?command('preferences',{typography:{...value,justify:e.currentTarget.checked}}):typography('justify',e.currentTarget.checked)}/> Justify text</label>
  <label class="check"><input data-book-control="hyphenate" type="checkbox" checked={value.hyphenate} onchange={e=>preference?command('preferences',{typography:{...value,hyphenate:e.currentTarget.checked}}):typography('hyphenate',e.currentTarget.checked)}/> Auto-hyphenation</label>
 </div>
{/snippet}
<div bind:this={root} class="books-app" class:classic={cap.classic} class:modern={!cap.classic&&!cap.windows} class:windows={cap.windows} class:golden={profile.id.includes('golden-gate')} class:inactive={!active} data-books-app data-window-no-drag onkeydown={key} ondragover={e=>e.preventDefault()} ondrop={drop} role="region" aria-label={cap.label} tabindex="-1">
 {#if session}
  {#if cap.classic||cap.windows||session.reader}<header class="titlebar" data-window-drag>{#if !cap.windows}<WindowControls {...controls} {active}/>{:else}<strong>{cap.label}</strong>{/if}<span class="window-title">{session.reader?selected?.title:cap.label}</span>{#if cap.windows}<div class="windows-controls"><button aria-label="Minimize" onclick={controls.onminimize}>−</button><button aria-label="Maximize" onclick={controls.onzoom}>□</button><button aria-label="Close" onclick={controls.onclose}>×</button></div>{/if}</header>{/if}
  {#if session.reader}
   <div class="reader-toolbar"><button title="Return to Library" aria-label="Library" data-book-control="library" onclick={()=>navigate(session.section)}>▣</button><button aria-label="Contents" data-book-control="contents" class:pressed={session.panel==='contents'} onclick={()=>panel('contents')}>☷</button><button aria-label="Notes" data-book-control="notes" onclick={()=>panel('notes')}>▤</button><span class="toolbar-space"></span><button class="appearance-button" aria-label="Appearance" data-book-control="appearance" onclick={()=>panel('appearance')}>aA</button><button aria-label="Search Book" data-book-control="find" onclick={()=>panel('search')}>⌕</button><button aria-label="Add Bookmark" data-book-control="bookmark" onclick={()=>command('bookmark',{operation:'add'})}>⚑</button><button aria-label="Show Bookmarks" data-book-control="bookmarks" onclick={()=>panel('bookmarks')}>⌄</button></div>
   <div class="reader-layout {session.typography.appearance}">
    {#if session.panel!=='none'}<aside class="reader-panel"><header><strong>{({contents:'Contents',bookmarks:'Bookmarks',notes:'Highlights & Notes',search:'Search',appearance:'Appearance'})[session.panel]}</strong><button aria-label="Close reader panel" onclick={()=>command('reader.panel',{panel:'none'})}>×</button></header>
     {#if session.panel==='contents'}{#each document?.toc??[] as row}<button class="toc-row" style:padding-left={12+row.depth*12+'px'} data-book-control={'toc-'+row.chapter+'-'+row.offset} onclick={()=>command('reader.navigate',{chapter:row.chapter,offset:row.offset})}>{row.title}</button>{/each}
     {:else if session.panel==='bookmarks'}{#each selected.bookmarks as mark}<div class="reader-record"><button data-book-control={'bookmark-'+mark.id} onclick={()=>command('bookmark',{operation:'navigate',bookmarkId:mark.id})}>{mark.label||`Chapter ${mark.chapter+1}`}<small>Chapter {mark.chapter+1} · {mark.offset}</small></button><button aria-label="Remove bookmark" onclick={()=>command('bookmark',{operation:'remove',bookmarkId:mark.id})}>×</button></div>{:else}<p class="empty-small">No bookmarks yet. Click the bookmark in the toolbar.</p>{/each}
     {:else if session.panel==='notes'}<p class="empty-small">Select text in the actual book, then add a highlight or note.</p><label>Highlight <select data-book-control="highlight-color" bind:value={highlightColor}>{#each ['yellow','green','blue','pink','purple'] as color}<option value={color}>{color}</option>{/each}</select></label><label>Note <textarea data-book-control="new-note" bind:value={note} maxlength="4096" placeholder="Your local note"></textarea></label><button data-book-control="add-highlight" disabled={!session.selection} onclick={addAnnotation}>Add Highlight / Note</button>{#each selected.annotations as mark}<div class="note-record"><button class="annotation-preview {mark.color}" data-book-control={'annotation-'+mark.id} onclick={()=>command('annotation',{operation:'navigate',annotationId:mark.id})}>{document?.chapters[mark.chapter]?.text.slice(mark.start,mark.end)??`Chapter ${mark.chapter+1}`}</button><textarea data-book-control={'note-'+mark.id} aria-label="Edit local note" value={mark.note} maxlength="4096" onchange={e=>command('annotation',{operation:'update',annotationId:mark.id,note:e.currentTarget.value})}></textarea><select aria-label="Highlight color" value={mark.color} onchange={e=>command('annotation',{operation:'update',annotationId:mark.id,color:e.currentTarget.value})}>{#each ['yellow','green','blue','pink','purple'] as color}<option value={color}>{color}</option>{/each}</select><button onclick={()=>command('annotation',{operation:'remove',annotationId:mark.id})}>Remove</button></div>{/each}
     {:else if session.panel==='search'}<input type="search" data-book-control="reader-search" aria-label="Search book" placeholder="Search this book" value={session.readerQuery} oninput={e=>command('reader.search',{query:e.currentTarget.value})}/><small>{matches.length} result{matches.length===1?'':'s'}{matches.length===1024?' (bounded)':''}</small>{#each matches as match,i}<button class="search-result" data-book-control={'match-'+i} onclick={()=>command('reader.match',{index:i})}><strong>Chapter {match.chapter+1}</strong><span>{match.text}</span></button>{/each}
     {:else}{@render appearance(session.typography)}{/if}
    </aside>{/if}
    <main class="reading-scroll" data-book-reader onscroll={scrolled} onmouseup={saveSelection} onkeyup={saveSelection} aria-label="EPUB chapter" tabindex="0">
     {#if loading}<div class="reader-empty">Reading actual EPUB resources…</div>{:else if chapter&&documentFile===readyFile(selected)}<article class="chapter-content" class:two-pages={session.typography.layout==='two'} style:font-family={session.typography.font==='sans'?'Helvetica, Arial, sans-serif':session.typography.font==='mono'?'ui-monospace, monospace':'Georgia, Times New Roman, serif'} style:font-size={session.typography.size+'px'} style:line-height={session.typography.lineHeight} style:text-align={session.typography.justify?'justify':'left'} style:hyphens={session.typography.hyphenate?'auto':'none'} lang={document.language||'en'}>
      {#each chapter.blocks as block}<div class="reading-block {block.kind}" data-book-block data-chapter={session.location.chapter} data-start={block.start} data-kind={block.kind} role={block.kind==='heading'?'heading':undefined} aria-level={block.kind==='heading'?block.level:undefined}>{#if block.kind==='image'}<img src={block.src} alt={block.text} onerror={()=>{message='The actual EPUB image could not be decoded by the native renderer.';}}/>{/if}<span data-book-text>{#each textRuns(block) as run}{#if run.color||run.found}<mark class={run.color} class:search-hit={run.found} title={run.note}>{run.text}</mark>{:else}{run.text}{/if}{/each}</span></div>{/each}
     </article>{:else}<div class="reader-empty">{message||'The original EPUB source is unavailable.'}</div>{/if}
    </main>
   </div>
   <footer class="reader-footer"><button data-book-control="previous" disabled={session.location.chapter===0} onclick={()=>command('reader.turn',{direction:-1})}>‹ Previous chapter</button><span>Chapter {session.location.chapter+1} of {selected.chapterLengths.length} · {Math.round(booksFraction(selected,session.location.chapter,session.location.offset)*100)}% read</span><button data-book-control="next" disabled={session.location.chapter>=selected.chapterLengths.length-1} onclick={()=>command('reader.turn',{direction:1})}>Next chapter ›</button></footer>
  {:else}
   {#if cap.classic}<div class="classic-toolbar"><button class="store-button" data-book-control="store" onclick={()=>navigate('store')}>{cap.label==='iBooks'?'iBooks Store':'Book Store'}</button><div class="segments">{#each [['all','All Books'],['collections','Collections'],['authors','Authors'],['categories','Categories'],['list','List']] as [section,label]}<button class:chosen={section==='list'?session.view==='list':section==='collections'?session.section.startsWith('collection:')&&session.view==='covers':session.section===section&&session.view==='covers'} onclick={async()=>{if(section==='list')return command('view',{view:'list'});if(section==='collections'&&!booksState.collections.length)return openSheet('collection');const result=await command('view',{view:'covers'});if(result?.status==='applied')navigate(section==='collections'?'collection:'+booksState.collections[0].id:section);}}>{label}</button>{/each}</div><input type="search" data-book-control="library-search" aria-label="Search library" placeholder="⌕ Search" value={session.query} oninput={e=>command('search',{query:e.currentTarget.value})}/></div>{/if}
   <div class="library-layout">
    {#if !cap.classic}<aside class="library-sidebar">{#if !cap.windows}<div class="sidebar-controls" data-window-drag><WindowControls {...controls} {active}/></div>{/if}<input type="search" data-book-control="library-search" aria-label="Search library" placeholder="⌕ Search" value={session.query} oninput={e=>command('search',{query:e.currentTarget.value})}/><strong>{cap.windows?'Local Books':'Apple Books'}</strong><button class:chosen={session.section==='all'} onclick={()=>navigate('all')}>⌂ Home</button><button class:chosen={session.section==='store'} data-book-control="store" onclick={()=>navigate('store')}>♧ Book Store</button><strong>Library</strong>{#each [['all','▥','All'],['finished','✓','Finished'],['books','▣','Books'],['pdfs','▤','PDFs'],['downloads','↓','Downloads']] as [section,icon,label]}<button class:chosen={session.section===section} data-book-control={'section-'+section} onclick={()=>navigate(section)}><span>{icon}</span> {label}</button>{/each}<strong>My Collections</strong>{#each booksState.collections as collection}<button class:chosen={session.section==='collection:'+collection.id} data-book-control={'collection-'+collection.id} onclick={()=>navigate('collection:'+collection.id)}>☰ {collection.name}</button>{/each}<button data-book-control="new-collection" onclick={()=>openSheet('collection')}>＋ New Collection</button><div class="sidebar-space"></div><button class="account-button" data-book-control="account" onclick={()=>navigate('account')}><span class="avatar">{booksState.account.signedIn?booksState.account.name.slice(0,1):'●'}</span>{booksState.account.signedIn?booksState.account.name:'Local Account'}</button></aside>{/if}
    <main class="library-main" data-book-scroll>
     <header class="library-heading"><h1>{heading}</h1><div class="library-tools"><button data-book-control="import" onclick={()=>command('import')}>{cap.classic?'Add to Library…':'Import…'}</button>{#if cap.classic}<select aria-label="Collection" value={session.section.startsWith('collection:')?session.section.slice(11):''} onchange={e=>e.currentTarget.value&&navigate('collection:'+e.currentTarget.value)}><option value="">Collections</option>{#each booksState.collections as collection}<option value={collection.id}>{collection.name}</option>{/each}</select>{/if}<button aria-label="More" data-book-control="menu" onclick={()=>command('sheet',{menu:session.menu?null:'file'})}>•••</button></div></header>
     {#if session.section==='store'}<div class="fiction-banner">Fictional Book Store · free local files only · no payments, subscriptions, DRM or network</div><div class="store-heading"><h2>Small stories. Real books.</h2><p>A hand-authored local catalogue. Downloads create genuine EPUB files you can reveal in Files.</p><input type="search" aria-label="Search fictional store" data-book-control="store-search" bind:value={storeQuery} placeholder="Search local catalogue"/></div><div class="store-books">{#each BOOKS_SEEDS.filter(seed=>`${seed.title} ${seed.author}`.toLowerCase().includes(storeQuery.toLowerCase())) as seed}<section class="store-book">{@render cover(seed)}<h3>{seed.title}</h3><p>{seed.author}</p><small>{seed.subtitle}</small><button data-book-control={'download-'+seed.id} disabled={booksState.books.some(b=>b.storeId===seed.id)} onclick={()=>command('download',{storeId:seed.id})}>{booksState.books.some(b=>b.storeId===seed.id)?'In Library':'Get · Free'}</button></section>{/each}</div>
     {:else if session.section==='account'}<section class="account-page"><div class="account-icon">♧</div><h2>Local Fictional Account</h2><p>This identity is stored only in this authored scene. No Apple/Microsoft account, password, server, purchase or DRM is involved.</p>{#if booksState.account.signedIn}<h3>{booksState.account.name}</h3><p>{booksState.account.email}</p><button data-book-control="signout" onclick={()=>command('account',{operation:'signout'})}>Sign Out of Local Account</button>{:else}<label>Fictional display name<input data-book-control="account-name" maxlength="256" bind:value={accountName}/></label><label>Fictional email<input data-book-control="account-email" maxlength="256" type="email" bind:value={accountEmail} placeholder="reader@example.test"/></label><button data-book-control="signin" onclick={()=>command('account',{operation:'signin',name:accountName,email:accountEmail})}>Use Local Account</button>{/if}<button onclick={()=>navigate('downloads')}>View Local Downloads</button></section>
     {:else if session.section==='downloads'}<p class="fiction-banner">Completed local file creations, not simulated network downloads.</p>{#each booksState.downloads as download}{@const book=booksState.books.find(b=>b.id===download.bookId)}<div class="download-row">{@render cover(book,true)}<div><strong>{book.title}</strong><small>{getFile?.(download.fileId)?.name??'Original File unavailable'}</small><span>EPUB · Completed</span></div><button onclick={()=>command('open',{},book.id)}>Read</button><button onclick={()=>command('reveal',{},book.id)}>Show in Files</button></div>{:else}<div class="empty-library"><h2>No local downloads</h2><p>Get a free fictional title from the Book Store.</p><button onclick={()=>navigate('store')}>Browse Book Store</button></div>{/each}
     {:else}<div class="sort-row"><span>{visible.length} {visible.length===1?'book':'books'}</span><label>Sort By <select data-book-control="sort" value={session.sort} onchange={e=>command('sort',{sort:e.currentTarget.value})}><option value="title">Title</option><option value="author">Author</option><option value="recent">Most Recent</option><option value="added">Date Added</option></select></label><button data-book-control="view" onclick={()=>command('view',{view:session.view==='covers'?'list':'covers'})}>{session.view==='covers'?'☷ List':'▦ Covers'}</button></div>{#each groups as group}{#if group.name&&group.books.length}<h2 class="group-heading">{group.name}</h2>{/if}{#if session.view==='covers'}<div class="covers-grid">{#each group.books as book}<div class="library-book" class:selected={session.selectedId===book.id}><button class="cover-button" data-book-control={'book-'+book.id} onclick={()=>command('select',{bookId:book.id})} ondblclick={()=>command('open',{},book.id)} aria-label={'Select '+book.title}>{@render cover(book)}</button><strong>{book.title}</strong><small>{book.author}</small><div class="book-meta"><span>{book.finished?'Finished':book.progress.fraction?`${Math.round(book.progress.fraction*100)}%`:'NEW'}{book.mime==='application/pdf'?' · PDF':''}{!readyFile(book)?' · Unavailable':''}</span><button aria-label={'Read '+book.title} disabled={!readyFile(book)} onclick={()=>command('open',{},book.id)}>•••</button></div></div>{/each}</div>{:else}<table class="books-list"><thead><tr><th>Title</th><th>Author</th><th>Kind</th><th>Progress</th></tr></thead><tbody>{#each group.books as book}<tr class:selected={session.selectedId===book.id}><td><button data-book-control={'book-'+book.id} onclick={()=>command('select',{bookId:book.id})} ondblclick={()=>command('open',{},book.id)}>{@render cover(book,true)}{book.title}</button></td><td>{book.author}</td><td>{book.mime==='application/pdf'?'PDF':'EPUB'}</td><td>{book.finished?'Finished':`${Math.round(book.progress.fraction*100)}%`}</td></tr>{/each}</tbody></table>{/if}{/each}{#if !visible.length}<div class="empty-library"><h2>{session.query?'No matching books':'No books in this collection'}</h2><p>Import an actual EPUB or PDF from Files, or browse the fictional Book Store.</p></div>{/if}{/if}
    </main>
   </div>
   <footer class="library-footer">{#if selected}<strong>{selected.title}</strong><button data-book-control="read" disabled={!readyFile(selected)} onclick={()=>command('open')}>{selected.mime==='application/pdf'?(cap.windows?'Open in Microsoft Edge':'Open in Preview'):'Read Book'}</button><button onclick={()=>command('finished',{enabled:!selected.finished})}>{selected.finished?'Mark Unfinished':'Mark Finished'}</button><button onclick={()=>openSheet('collection')}>Collection…</button><button onclick={()=>openSheet('remove')}>Remove…</button>{:else}<span>{cap.classic?'Double-click a book to read.':'Select a book to read or organize.'}</span>{/if}{#if cap.classic}<span class="toolbar-space"></span><button onclick={()=>navigate('account')}>Account</button><button onclick={()=>navigate('downloads')}>Downloads</button><button onclick={()=>openSheet('collection')}>＋ Collection</button>{/if}</footer>
  {/if}
  <div class="availability">{cap.availability} <button data-book-control="preferences" onclick={()=>openSheet('preferences')}>{cap.classic?'Preferences…':'Settings…'}</button></div>
  {#if message}<p class="status" role="status">{message}</p>{/if}
  {#if session.menu}{@const menu=menus.find(m=>m.id===session.menu)}<div class="menu-popup" role="menu" aria-label={menu?.label}>{#each menu?.children??[] as item}<button role="menuitem" disabled={!item.enabled} onclick={()=>menuItem(item)}>{item.checked?'✓ ':''}{item.label}<span>{item.shortcut??''}</span></button>{/each}<button onclick={()=>command('sheet',{menu:null})}>Close Menu</button></div>{/if}
  {#if session.sheet}<div class="sheet-shade"><section class="books-sheet" data-book-sheet role="dialog" aria-modal="true" aria-label={session.sheet}><header><h2>{session.sheet==='preferences'?`${cap.label} ${cap.classic?'Preferences':'Settings'}`:session.sheet==='collection'?'Collections':session.sheet==='remove'?'Remove from Library?':`${cap.label} Help`}</h2><button aria-label="Close dialog" data-book-control="close-sheet" onclick={()=>command('sheet',{sheet:null})}>×</button></header>
   {#if session.sheet==='preferences'}<p class="sheet-tabs">General · Reading</p><label>Default library view <select data-book-control="default-view" value={booksState.preferences.defaultView} onchange={e=>command('preferences',{defaultView:e.currentTarget.value})}><option value="covers">Covers</option><option value="list">List</option></select></label><h3>Default Reading Appearance</h3>{@render appearance(booksState.preferences.typography,true)}<p class="empty-small">Defaults apply to new windows. Current readers retain independent typography. Account, downloads, notes and bookmarks stay local; no cloud synchronization.</p>
   {:else if session.sheet==='collection'}<label>Collection <select data-book-control="collection-choice" bind:value={collectionId}><option value="">New collection</option>{#each booksState.collections as collection}<option value={collection.id}>{collection.name}</option>{/each}</select></label><label>Name <input data-book-control="collection-name" bind:value={collectionName} maxlength="256"/></label><div class="sheet-actions"><button onclick={()=>collection(collectionId?'rename':'create')} disabled={!collectionName.trim()}>{collectionId?'Rename':'Create'}</button>{#if collectionId}<button onclick={()=>collection('delete')}>Delete Collection</button>{#if selected}<button onclick={()=>collection('add')}>Add Selected Book</button><button onclick={()=>collection('remove')}>Remove Selected Book</button>{/if}{/if}</div>
   {:else if session.sheet==='remove'}<p>Remove “{selected?.title}” from this local library? Its original EPUB/PDF remains in Files. Bookmarks, highlights, notes and collection membership for this entry will be removed.</p><div class="sheet-actions"><button onclick={()=>command('sheet',{sheet:null})}>Cancel</button><button class="destructive" data-book-control="confirm-remove" onclick={()=>command('remove',{confirm:true})}>Remove from Library</button></div>
   {:else}<p>{cap.availability}</p><p>Import genuine EPUB or PDF Files. EPUB uses bounded ZIP/container/package/spine/contents parsing, actual text selection, bookmarks, highlights, local notes and appearance controls. PDF opens in the actual native Preview/Edge reader; reading progress is recorded only after a native page renders.</p><p>Supported local EPUB: UTF-8 EPUB 2/3, stored/deflated ZIP, linear XHTML chapters with genuine EPUB 3 navigation or EPUB 2 NCX, PNG/JPEG images. Missing/empty contents, nonlinear contents targets, right-to-left progression, encrypted/DRM, DTD entities, active/multimedia content, ZIP64, external resources and oversized archives produce explicit errors, not fabricated pages.</p><p>All store titles and accounts are authored fiction. No purchases, passwords, server sign-in, cloud services or DRM integration.</p>{/if}
  </section></div>{/if}
 {:else}<div class="empty-library">The original Books window session is unavailable.</div>{/if}
</div>

